/**
 * Body and query id hints: which request fields carry ids, per route, taken
 * from the backend's own validation schemas (`validate(Schema, request.body)`
 * and `validate(Schema, request.query)` next to each route registration).
 *
 * `body-hints.json` is generated by `gen-body-hints.ts` and committed. Route
 * registrations use a prefix variable (`${prefix}/units/:id`), so a hint
 * stores the literal tail as a pattern and is matched to inventory routes by
 * shape, preferring the most specific pattern and the backend package whose
 * name appears in the path.
 */
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import type { ApiRoute, HttpMethod } from '../../foundation/index.js';

import type { IdField } from './schema-sample.js';

export interface RouteHint {
  /** Backend package dir (`fees`) or `api-gateway`. */
  module: string;
  file: string;
  method: HttpMethod;
  /** Registration path with `${...}` replaced by `*` (`*\/units/:id`). */
  pattern: string;
  bodySchema?: string;
  querySchema?: string;
  bodyTemplate?: unknown;
  queryTemplate?: Record<string, unknown>;
  bodyIdFields: IdField[];
  queryIdFields: IdField[];
}

export interface BodyHintsFile {
  $comment: string;
  generatedFrom: string;
  hints: RouteHint[];
  /** Registrations whose schema could not be loaded (reported as coverage gaps). */
  unresolvedSchemas: Array<{
    module: string;
    file: string;
    method: string;
    pattern: string;
    schema: string;
  }>;
}

export const BODY_HINTS_FILE = join(dirname(fileURLToPath(import.meta.url)), 'body-hints.json');

export function loadBodyHints(file = BODY_HINTS_FILE): BodyHintsFile {
  const doc = JSON.parse(readFileSync(file, 'utf8')) as BodyHintsFile;
  if (!Array.isArray(doc.hints)) throw new Error(`${file}: hints must be an array`);
  for (const h of doc.hints) {
    if (
      !h.method ||
      !h.pattern ||
      !Array.isArray(h.bodyIdFields) ||
      !Array.isArray(h.queryIdFields)
    ) {
      throw new Error(`${file}: malformed hint ${JSON.stringify(h).slice(0, 120)}`);
    }
  }
  return doc;
}

/** Regex for a registration pattern: `*` is one or more segments at the start, one segment elsewhere. */
export function patternRegex(pattern: string): RegExp {
  const parts = pattern.split('/');
  const body = parts
    .map((seg, i) => {
      if (seg === '*') return i <= 1 ? '(?:/[^/]+)*' : '/[^/]+';
      if (seg.startsWith(':')) return i === 0 ? '' : '/[^/]+';
      if (seg === '' && i === 0) return '';
      const lit = seg.replace(/[.*+?^${}()|[\]\\]/g, '\\$&').replace(/\\\*/g, '[^/]*');
      return i === 0 ? lit : `/${lit}`;
    })
    .join('');
  return new RegExp(`^${body}$`);
}

/** Shape key with param names erased, for comparing paths. */
export function shapeOf(path: string): string {
  return path.replace(/:[A-Za-z0-9_]+/g, ':');
}

function literalWeight(pattern: string): number {
  return pattern
    .split('/')
    .filter((s) => s && s !== '*' && !s.startsWith(':'))
    .join('/').length;
}

function moduleTokens(module: string): string[] {
  const stem = module.replace(/-/g, '');
  const out = new Set([module, stem, `${module}s`, module.replace(/s$/, '')]);
  return [...out];
}

/** Best hint for a route, or undefined when none or an unresolvable tie. */
export function matchHint(
  route: Pick<ApiRoute, 'method' | 'path'>,
  hints: readonly RouteHint[],
): RouteHint | undefined {
  const shape = shapeOf(route.path);
  const segs = route.path.split('/').map((s) => s.toLowerCase().replace(/-/g, ''));
  const moduleInPath = (h: RouteHint) =>
    moduleTokens(h.module).some((t) => segs.includes(t.replace(/-/g, '')));
  const candidates = hints.filter((h) => {
    if (h.method !== route.method || !patternRegex(shapeOf(h.pattern)).test(shape)) return false;
    // A prefix-relative pattern with a short literal tail (`${prefix}`, `${prefix}/:id`)
    // would match every module: require the package name in the path.
    if (h.pattern.startsWith('*') && literalWeight(h.pattern) < 6) return moduleInPath(h);
    return true;
  });
  if (candidates.length <= 1) return candidates[0];
  const score = (h: RouteHint) =>
    literalWeight(h.pattern) * 10 +
    (moduleInPath(h) ? 5 : 0) +
    (h.pattern.startsWith('/api/') ? 3 : 0);
  const ranked = [...candidates].sort((a, b) => score(b) - score(a));
  const [best, second] = ranked;
  if (!best) return undefined;
  if (second && score(second) === score(best)) {
    // Same schema fields on both: harmless tie.
    const same =
      JSON.stringify(best.bodyTemplate) === JSON.stringify(second.bodyTemplate) &&
      JSON.stringify(best.queryIdFields) === JSON.stringify(second.queryIdFields);
    return same ? best : undefined;
  }
  return best;
}

// ---------------------------------------------------------------------------
// Static scan used by the generator (pure, unit tested).

export interface Registration {
  method: HttpMethod;
  pattern: string;
  bodySchema?: string;
  querySchema?: string;
}

const REG_RE =
  /\b[A-Za-z_$][\w$]*\.(get|post|put|patch|delete)\s*(?:<[^>]*>+)?\s*\(\s*(['"`])((?:\/|\$\{)(?:(?!\2)[^\n])*)\2/g;
const VALIDATE_RE = /\bvalidate\(\s*([A-Za-z_$][\w$]*)\s*,\s*(?:request|req)\.(body|query)\b/g;

export function normaliseRegistrationPath(raw: string): string {
  const p = raw.replace(/\$\{[^}]*\}/g, '*').replace(/\/+$/, '');
  return p.replace(/\{([^}]+)\}/g, ':$1') || '/';
}

/** Route registrations in one source file with the schema each handler validates its body/query with. */
export function scanRegistrations(source: string): Registration[] {
  const marks: Array<{ index: number; method: HttpMethod; pattern: string }> = [];
  for (const m of source.matchAll(REG_RE)) {
    marks.push({
      index: m.index ?? 0,
      method: (m[1] ?? 'get').toUpperCase() as HttpMethod,
      pattern: normaliseRegistrationPath(m[3] ?? ''),
    });
  }
  const out: Registration[] = [];
  marks.forEach((mark, i) => {
    const end = marks[i + 1]?.index ?? source.length;
    const block = source.slice(mark.index, end);
    const reg: Registration = { method: mark.method, pattern: mark.pattern };
    for (const v of block.matchAll(VALIDATE_RE)) {
      if (v[2] === 'body' && !reg.bodySchema) reg.bodySchema = v[1];
      if (v[2] === 'query' && !reg.querySchema) reg.querySchema = v[1];
    }
    out.push(reg);
  });
  return out;
}
